func Test_getAmazonLinuxVersion(t *testing.T) {
	tests := []struct {
		release string
		want    string
	}{
		{
			release: "2017.09",
			want:    "1",
		},
		{
			release: "2018.03",
			want:    "1",
		},
		{
			release: "1",
			want:    "1",
		},
		{
			release: "2",
			want:    "2",
		},
		{
			release: "2022",
			want:    "2022",
		},
		{
			release: "2023",
			want:    "2023",
		},
		{
			release: "2023.3.20240312",
			want:    "2023",
		},
		{
			release: "2025",
			want:    "2025",
		},
		{
			release: "2027",
			want:    "2027",
		},
		{
			release: "2029",
			want:    "2029",
		},
		{
			release: "2031",
			want:    "unknown",
		},
	}
	for _, tt := range tests {
		t.Run(tt.release, func(t *testing.T) {
			if got := getAmazonLinuxVersion(tt.release); got != tt.want {
				t.Errorf("getAmazonLinuxVersion() = %v, want %v", got, tt.want)
			}
		})
	}
}
